(IsFullyWithdrawable() or IsPartiallyWithdrawable()):

 if validator.IsFullyWithdrawable(balance, epoch) {
    withdrawals = append(withdrawals, withdrawal.New(
        math.U64(withdrawalIndex),
        validatorIndex,
        withdrawalAddress,
        balance,
