5.3.8 deposit.Service race condition in failedBlocks field
Severity: Medium Risk
Context: execution/pkg/deposit/sync.go#L95
Description: The s.failedBlocks map is used concurrently in the depositCatchupFetcher() and in the de-
positFetcher().
The manner in which this map is used concurrently is seemingly safe - a single map key index is never accessed
concurrently, only separate key indices. This is guaranteed by the strictly increasing nature of the key value
blockNums that comes from the finalized block event stream.
However, the go map implementation can move, reallocate, or resize underlying data during write operations and
key deletion operations, and it is not safe to read/write concurrently without risk of undefined behavior.
Here is a mock program that closely imitates the deposit fetcher and results in fatal error: concurrent map
writes:
package main

import (
    "context"
    "time"
)

type Service struct {
    failedBlocks map[uint64]struct{}
}

 func (s *Service) depositFetcher(ctx context.Context, blockNum uint64) {
    s.fetchAndStoreDeposits(blockNum)
}

func (s *Service) eventLoop(ctx context.Context, subFinalizedBlockNums chan uint64) {
    for {
        select {
        case <-ctx.Done():
            return
        case blockNum := <-subFinalizedBlockNums:
            s.depositFetcher(ctx, blockNum)
        }
    }

}

func (s *Service) fetchAndStoreDeposits(blockNum uint64) {
    // Fail every 5 times for testing
    if blockNum%5 == 0 {
        s.failedBlocks[blockNum] = struct{}{}
        return
    }
    delete(s.failedBlocks, blockNum)

}

func (s *Service) depositCatchupFetcher(ctx context.Context) {
    ticker := time.NewTicker(5 * time.Second)
    defer ticker.Stop()
    for {
        select {
        case <-ctx.Done():
            return
        case <-ticker.C:
            if len(s.failedBlocks) == 0 {
                continue
            }
            for blockNum := range s.failedBlocks {
                s.fetchAndStoreDeposits(blockNum)
            }
        }
    }
}

func main() {
    ctx := context.Background()
    depositService := &Service{
        make(map[uint64]struct{}),
    }
    mockFinalizedBlockNums := make(chan uint64)
    go depositService.eventLoop(ctx, mockFinalizedBlockNums)
    go depositService.depositCatchupFetcher(ctx)
    for i := 0; i < 1000000000; i++ {
        mockFinalizedBlockNums <- uint64(i)
    }
}

Recommendation: Use a sync.RWMutex to protect s.failedBlocks or make s.failedBlocks into a sync.Map.
