    uint8 callIndex;
    // ...
}
function _bidFindingIteration(/*...*/ ) /*...*/ {
    // ...
    for (uint256 i; i < solverOps.length; i++) {
        bidPlaceholder = _getBidAmount(dConfig, userOp, solverOps[i], returnData, key);
        // ...
    }
