  if (collateralDecimals < lvlUsdDecimals) {
      lvlUSDAmount =
           collateralAmount *
           (10 ** (lvlUsdDecimals - collateralDecimals));
  } else if (collateralDecimals > lvlUsdDecimals) {
      lvlUSDAmount =
           collateralAmount /
           (10 ** (collateralDecimals - lvlUsdDecimals));
