    }

    struct VestingSchedule {
        uint256 start;
        uint256 cliffDuration;
        uint256 lockDuration;
        uint256 duration;
        uint256 period;
        uint256 amount;
        address beneficiary;
        address delegatee;
        bool revocable;
    }

    function createVestingSchedule(VestingSchedule memory config) internal returns (uint256) {
        return createVestingScheduleStackOptimized(config);
    }

    function createVestingScheduleStackOptimized(VestingSchedule memory config) internal returns
! (uint256) {
,

        return
            tlc.createVestingSchedule(
                uint64(config.start),
                uint32(config.cliffDuration),
                uint32(config.duration),
                uint32(config.period),
                uint32(config.lockDuration),
                config.revocable,
                config.amount,
                config.beneficiary,
                config.delegatee
            );
    }

 }

Recommendation: Consider re-implementing how the contract accounts for the amount of released tokens of a
vesting schedule to avoid this situation. In case the new implementation does not rely anymore on balanceOf(_-
escrow), remember that tokens sent directly to the escrow account would be stuck forever.
Alluvial: Fixed in liquid-collective/liquid-collective-protocol@7870787 by introducing a new variable inside the user
vesting schedule named releasedAmount that tracks the already released amount and can not be manipulated by
an external attacker.
Spearbit: Fixed.


7.2     Medium Risk

6.3.6   Avoid multiple divisions when calculating operatorRewards
Severity: Medium Risk
Context: River.1.sol#L277
Description/Recommendation: In _onEarnings, we calculate the sharesToMint and operatorRewards by div-
ing 2 numbers. We can reduce the number of divisions to 1 and also delegate this division to _rewardOperators.
This would further avoid the rounding errors that we would get when we divide two numbers in EVM. So in:
uint256 globalFee = GlobalFee.get();
uint256 numerator = _amount * currentTotalSupply * globalFee;
uint256 denominator = (_assetBalance() * BASE) - (_amount * globalFee);
uint256 sharesToMint = denominator == 0 ? 0 : (numerator / denominator);

uint256 operatorRewards = (sharesToMint * OperatorRewardsShare.get()) / BASE;

uint256 mintedRewards = _rewardOperators(operatorRewards);

Instead of passing operatorRewards we can pass 2 values, one for the numerator and one for the denominator.
This way we can avoid extra rounding errors introduced in _rewardOperators. _rewardOperators also need to be
changed slightly to account for these 2 new values.
uint256 globalFee = GlobalFee.get();
uint256 numerator = _amount * currentTotalSupply * globalFee * OperatorRewardsShare.get();
uint256 denominator = ((_assetBalance() * BASE) - (_amount * globalFee)) * BASE;

uint256 mintedRewards;

if(denominator != 0) { // note: this was added to avoid calling `_rewardOperators` if `denominator == 0`
   mintedRewards = _rewardOperators(numerator, denominator);
}

Without this correction, the rounding errors are in favor of the general users/stakers and the treasury of the River
protocol (not the operators).
Alluvial: The whole operator rewarding system has been removed in SPEARBIT/8.
Spearbit: Acknowledged.

6.3.7   Shares distributed to operators suffer from rounding error
Severity: Medium Risk
Context: River.1.sol#L238
Description: _rewardOperators distribute a portion of the overall shares distributed to operators based on the
number of active and funded validators that each operator has.
The current number of shares distributed to a validator is calculated by the following code
_mintRawShares(operators[idx].feeRecipient, validatorCounts[idx] * rewardsPerActiveValidator);

where rewardsPerActiveValidator is calculated as
uint256 rewardsPerActiveValidator = _reward / totalActiveValidators;

This means that in reality each operator receives validatorCounts[idx] * (_reward / totalActiveValida-
tors) shares. Such share calculation suffers from a rounding error caused by division before multiplication.
Recommendation: Consider re-writing the number of shares distributed to each operator:

 // removed --- > uint256 rewardsPerActiveValidator = _reward / totalActiveValidators;

for (uint256 idx = 0; idx < validatorCounts.length;) {
    _mintRawShares(
       operators[idx].feeRecipient,
       (validatorCounts[idx] * _reward) / totalActiveValidators;
    );
    ...

Note that this will reduce the rounding error, but it adds 1 DIV gas cost (5 gas) per iteration. Also, the rounding
errors favors the users/depositors.
Alluvial: The whole operator rewarding system has been removed in SPEARBIT/8.
Spearbit: Acknowledged.

3.1.1 Late repayment penalty on interest can be circumvented

Severity: High Risk
Context: CreditBroker.sol#L551-L566, CreditBroker.sol#L568-L580
Description: CreditBroker::_repay first repays the interest owed by a position and then proceeds to
pay down the principal if there are any funds left over. If the borrower exceeds the grace period following
the fixed loan end timestamp, an additional 15% penalty is applied to the repayment. However, the penalty
on the interest can be circumvented by users who split repayment into two separate transactions, as
opposed to settling the entire debt in one transaction.
This is due to the entire penalty calculation being deferred to the principal repay-
ment conditional block in which the outstanding interest is passed as an argument to
CreditBrokerMath::getPenaltyForCreditPosition .                 Penalties on interest can therefore be
avoided by first paying exactly the outstanding interest balance, such that repayPrincipalAmt evaluates
to zero and the penalty calculation is skipped. The principal amount can then be repaid in a separate
transaction, with the interest contribution being omitted from the penalty calculation as there is no
remaining interest.
Proof of Concept: The following test should be added to Broker.t.sol :
function test_circumventInterestPenalty() public {
  vm.prank(MANAGER);
  moolah.setProvider(id, address(broker), true);

    uint256 termId = 66;
    FixedTermAndRate memory term = FixedTermAndRate({
      termId: termId,
      duration: 14 days,
      apr: 105 * 1e25,
      termType: type1
    });
    vm.prank(BOT);
    broker.updateFixedTermAndRate(term, false);

    _generateTree(borrower, COLLATERAL, creditToken.versionId() + 1);

    vm.startPrank(borrower);
    creditToken.approve(address(broker), COLLATERAL);
    broker.supplyAndBorrow(marketParams, COLLATERAL, COLLATERAL, termId, COLLATERAL,
     ,→ proof);
    vm.stopPrank();

    // Advance time past grace period (14 days term + 3 days grace + 3 days extra = 20
     ,→ days)
    skip(20 days);
    moolah.accrueInterest(marketParams);

    // Verify position is penalized
    FixedLoanPosition[] memory positions = broker.userFixedPositions(borrower);
    assertEq(positions.length, 1, "missing fixed position");
    FixedLoanPosition memory pos = positions[0];
    uint256 posId = pos.posId;
    assertTrue(broker.isPositionPenalized(borrower, posId), "position should be
     ,→ penalized");

    // Calculate what the user owes
    uint256 interestDue = CreditBrokerMath.getAccruedInterestForFixedPosition(pos) -
     ,→ pos.interestRepaid;
    uint256 principalDue = pos.principal - pos.principalRepaid;

    console.log("=== POSITION STATE ===");

     console.log("Principal due:", principalDue);
    console.log("Interest due:", interestDue);

    // Take snapshot before any repayment
    uint256 snapshotId = vm.snapshot();

    // ==================== SCENARIO A: SINGLE TRANSACTION ====================
    console.log("");
    console.log("=== SCENARIO A: Full repayment ===");

    uint256 startBalanceA = 2_500 ether;
    USDT.setBalance(borrower, startBalanceA);

    vm.startPrank(borrower);
    USDT.approve(address(broker), startBalanceA);
    broker.repayAndWithdraw(marketParams, COLLATERAL, startBalanceA, posId, COLLATERAL,
     ,→ proof);
    vm.stopPrank();

    uint256 endBalanceA = USDT.balanceOf(borrower);
    uint256 totalCostA = startBalanceA - endBalanceA;
    console.log("Total cost:", totalCostA);

    // Revert to snapshot
    vm.revertTo(snapshotId);

    // ==================== SCENARIO B: TWO TRANSACTIONS ====================
    console.log("");
    console.log("=== SCENARIO B: Interest first, then principal) ===");

    uint256 startBalanceB = 2_500 ether;
    USDT.setBalance(borrower, startBalanceB);

    vm.startPrank(borrower);
    USDT.approve(address(broker), startBalanceB);

    // First tx: pay only the interest
    broker.repay(interestDue, posId, borrower);
    console.log("First tx - paid interest:", interestDue);

    // Second tx: pay remaining principal + penalty
    broker.repayAndWithdraw(marketParams, COLLATERAL, startBalanceB, posId, COLLATERAL,
     ,→ proof);
    vm.stopPrank();

    uint256 endBalanceB = USDT.balanceOf(borrower);
    uint256 totalCostB = startBalanceB - endBalanceB;
    console.log("Total cost:", totalCostB);

    // ==================== VERIFY BUG ====================
    console.log("");
    console.log("=== BUG VERIFICATION ===");
    console.log("Full repayment total cost:", totalCostA);
    console.log("Separate repayment total cost:", totalCostB);

    // Verify the bug exists: single tx should pay more than two tx due to interest penalty
    assertTrue(totalCostA > totalCostB, "Single tx expected to pay more due to interest
     ,→ penalty");

    console.log("Separate repayment underpays by interest penalty:", totalCostA -
     ,→ totalCostB);
}

Recommendation: Ensure that the late repayment penalty is also applied to interest-only repayments.
