        console2.log("Validator 1 stake:", s1);
        console2.log("Validator 2 stake:", s2);
        console2.log("========================");
    }

    function test_InitiationCausesInflation() public {
        // Snapshot state before initiation
        uint256 initialAssets = vault.totalAssets();
        (uint256 stakeToRemove,,,,,,) = MockStaking(PRECOMPILE).getDelegator(TEST_VAL_ID_1, address(vault));
        uint256 expectedInflated = initialAssets + stakeToRemove;
        console2.log("==== Before initiateValidatorRemoval ====");
        console2.log("Initial totalAssets:", initialAssets);
        console2.log("Stake on removed validator (v1):", stakeToRemove);
        console2.log("Expected inflated totalAssets after initiation (initial + stake(v1)):", expectedInflated);

        // Initiate removal of v1
        vm.prank(address(this));
        vault.initiateValidatorRemoval(TEST_VAL_ID_1);

        // Check for inflation: Expected = initialAssets + stakeToRemove (double-count)
        uint256 assetsAfterInit = vault.totalAssets();
        console2.log("==== After initiateValidatorRemoval ====");
        console2.log("Observed totalAssets:", assetsAfterInit);
        console2.log("Inflation delta:", assetsAfterInit - initialAssets);
        console2.log("Reason: _initiateValidatorRemoval adds stake(v1) to totalPendingRedelegation while
        ,→  stake(v1) remains in cachedTotalAssets (no offset).\n");
        assertEq(assetsAfterInit, expectedInflated, "totalAssets inflated incorrectly after initiation");
    }
}


Impact:
    • Users depositing during the interim window (after initiateValidatorRemoval and before executeVal-
      idatorUndelegation or a cache refresh) can receive fewer shares than they should, since totalAssets
      is inflated and ERC-4626-style minting divides by a larger denominator.
    • External systems relying on CoreVault's totalAssets (e.g., TVL reporting, risk checks, caps) will observe
      a temporarily inflated value.
Recommendation: Call _trackCachedUndelegation(_totalStakedToValidator) there to net the account-
ing to zero during the queue.
