         let expiry_ts: i64 = current_ts() + days(7) as i64;
         let nonce = 0;

          let (mut litesvm, alice, bob, delegation_pda, mint, _, bob_ata, _) =
              setup_recurring_delegation(
                  amount_per_period,
                  period_length_s,

                    start_ts,
                   expiry_ts,
                   nonce,
              );

         assert_eq!(get_ata_balance(&litesvm, &bob_ata), 0);

         // Transfer BEFORE start_ts - current time is ~now, start_ts is +1 day.
         let transfer_amount: u64 = 10_000_000;
         let result =
             TransferDelegation::new(&mut litesvm, &bob, alice.pubkey(), mint,
              ,→ delegation_pda)
                 .amount(transfer_amount)
                 .recurring();

         // Bug: transfer succeeds even though the delegation period hasn't started.
         result.assert_ok();
         assert_eq!(
             get_ata_balance(&litesvm, &bob_ata),
             transfer_amount,
             "Delegatee was able to transfer before start_ts"
         );
     }

Recommendation: It is recommended to add an explicit check that current_ts is at or past
current_period_start_ts before proceeding with the transfer validation.

if current_ts < *current_period_start_ts {
    return Err(MultiDelegatorError::DelegationNotStarted.into());
}

