  await usdc.connect(deployer).transfer(liquidityPool, 1n * USDC);
  await liquidityHub.connect(admin).adjustTotalAssets(1n * USDC, INCREASE);

  expect(await liquidityPool.balance(usdc)).to.equal(11n * USDC);
